// Combine ClickUp, GitHub PRs, CI/CD, Security, and Monitoring signals into
// one weighted 0-100 Engineering Health Score, with per-pillar sub-scores.
const cfg = $('Set - Config').first().json;
const all = $input.first().json;

const clickupData = all.clickup || all[0] || {};
const prData = all.pulls || all[1] || [];
const ciData = all.ci || all[2] || {};
const securityData = all.security || all[3] || {};
const monitoringData = all.monitoring || all[4] || {};

const tasks = clickupData.tasks || (Array.isArray(clickupData) ? clickupData : []);
const now = Date.now();
const overdueTasks = tasks.filter(t => t.due_date && Number(t.due_date) < now && t.status && t.status.status !== 'complete');
const blockedTasks = tasks.filter(t => (t.tags || []).some(tg => /blocked/i.test(tg.name || '')));
const deliveryPenalty = Math.min(60, overdueTasks.length * 6 + blockedTasks.length * 8);
const deliveryScore = Math.max(0, 100 - deliveryPenalty);

const prs = Array.isArray(prData) ? prData : (prData.pulls || []);
const staleMs = 1000 * 60 * 60 * 24 * 3;
const stalePRs = prs.filter(p => p.updated_at && (now - new Date(p.updated_at).getTime()) > staleMs);
const unreviewedPRs = prs.filter(p => (p.requested_reviewers || []).length > 0 && !p.review_comments);
const codePenalty = Math.min(60, stalePRs.length * 7 + unreviewedPRs.length * 5);
const codeScore = Math.max(0, 100 - codePenalty);

const runs = ciData.workflow_runs || (Array.isArray(ciData) ? ciData : []);
const recentRuns = runs.slice(0, 15);
const failedRuns = recentRuns.filter(r => r.conclusion === 'failure');
const ciFailureRate = recentRuns.length ? failedRuns.length / recentRuns.length : 0;
const ciScore = Math.max(0, Math.round(100 - ciFailureRate * 100));

const findings = securityData.findings || securityData.vulnerabilities || (Array.isArray(securityData) ? securityData : []);
const criticalFindings = findings.filter(f => /critical|high/i.test(f.severity || ''));
const securityPenalty = Math.min(70, criticalFindings.length * 12 + Math.max(0, findings.length - criticalFindings.length) * 3);
const securityScore = Math.max(0, 100 - securityPenalty);

const errorRate = Number(monitoringData.errorRatePercent ?? monitoringData.error_rate ?? 0);
const p95LatencyMs = Number(monitoringData.p95LatencyMs ?? monitoringData.latency_p95 ?? 0);
const uptimePercent = Number(monitoringData.uptimePercent ?? monitoringData.uptime ?? 100);
let productionScore = 100;
productionScore -= Math.min(50, errorRate * 10);
productionScore -= Math.min(30, Math.max(0, (p95LatencyMs - 300) / 20));
productionScore -= Math.min(40, Math.max(0, (100 - uptimePercent) * 20));
productionScore = Math.max(0, Math.round(productionScore));

const WEIGHTS = { delivery: 0.2, code: 0.2, ci: 0.2, security: 0.2, production: 0.2 };
const overallScore = Math.round(
  deliveryScore * WEIGHTS.delivery +
  codeScore * WEIGHTS.code +
  ciScore * WEIGHTS.ci +
  securityScore * WEIGHTS.security +
  productionScore * WEIGHTS.production
);

const pillars = {
  delivery: { score: deliveryScore, overdueTasks: overdueTasks.length, blockedTasks: blockedTasks.length },
  code: { score: codeScore, stalePRs: stalePRs.length, unreviewedPRs: unreviewedPRs.length },
  ci: { score: ciScore, failedRuns: failedRuns.length, totalRecentRuns: recentRuns.length },
  security: { score: securityScore, criticalFindings: criticalFindings.length, totalFindings: findings.length },
  production: { score: productionScore, errorRatePercent: errorRate, p95LatencyMs, uptimePercent }
};

let overallStatus = 'healthy';
if (overallScore < cfg.healthCriticalThreshold) overallStatus = 'critical';
else if (overallScore < cfg.healthDegradedThreshold) overallStatus = 'degraded';

const atRiskPillars = Object.entries(pillars)
  .filter(([, v]) => v.score < cfg.healthDegradedThreshold)
  .map(([k]) => k);

const whatsappMessage = 'Engineering Health Score: ' + overallScore + '/100 (' + overallStatus.toUpperCase() + ')\n' +
  'Delivery: ' + deliveryScore + ' | Code: ' + codeScore + ' | CI/CD: ' + ciScore + ' | Security: ' + securityScore + ' | Production: ' + productionScore + '\n' +
  'At-risk pillars: ' + (atRiskPillars.length ? atRiskPillars.join(', ') : 'none') + '\n' +
  'Overdue tasks: ' + overdueTasks.length + ' | Stale PRs: ' + stalePRs.length + ' | Failed CI runs: ' + failedRuns.length + ' | Critical vulns: ' + criticalFindings.length + ' | Error rate: ' + errorRate + '%';

return [{
  json: {
    ...cfg,
    overallScore,
    overallStatus,
    pillars,
    atRiskPillars,
    whatsappMessage,
    rawTasks: tasks,
    rawPRs: prs,
    rawCIRuns: runs,
    rawFindings: findings,
    rawMonitoring: monitoringData
  }
}];

// Correlate signals across ClickUp, GitHub, Security, and Monitoring that a
// single-system view would miss. Emits the health-score item plus one item
// per correlated issue found.
const item = $input.first().json;

const correlations = [];

const overdueTaskNames = (item.rawTasks || [])
  .filter(t => t.due_date && Number(t.due_date) < Date.now() && t.status && t.status.status !== 'complete')
  .map(t => (t.name || '').toLowerCase());

for (const pr of (item.rawPRs || [])) {
  const branch = (pr.head && pr.head.ref || '').toLowerCase();
  const title = (pr.title || '').toLowerCase();
  const matchesOverdueTask = overdueTaskNames.some(name => name && (branch.includes(name.split(' ')[0]) || title.includes(name.split(' ')[0])));
  const relatedFailedRun = (item.rawCIRuns || []).find(r => r.head_branch === pr.head?.ref && r.conclusion === 'failure');
  if (matchesOverdueTask && relatedFailedRun) {
    correlations.push({
      correlationType: 'overdue_task_blocked_by_failing_ci',
      pr: pr.title,
      branch: pr.head?.ref,
      note: 'PR appears linked to an overdue ClickUp task and has a failing CI run on the same branch.'
    });
  }
}

const criticalFindingComponents = (item.rawFindings || [])
  .filter(f => /critical|high/i.test(f.severity || ''))
  .map(f => (f.package || f.component || '').toLowerCase())
  .filter(Boolean);

if (criticalFindingComponents.length > 0 && item.pillars.production.errorRatePercent > 1) {
  correlations.push({
    correlationType: 'security_finding_with_elevated_errors',
    components: criticalFindingComponents,
    errorRatePercent: item.pillars.production.errorRatePercent,
    note: 'Critical/high security findings exist while production error rate is elevated — investigate whether they are related.'
  });
}

return [{
  json: {
    ...item,
    correlations,
    correlationCount: correlations.length
  }
}];

